import React from 'react';

function Photography(){
    return(
        <>
            <div className="flex items-center space-x-4 pl-5 pt-10"> 
                <p className="underline text-lg sm:text-xl lg:text-2xl">Go Back</p>
                <h1 className="text-6xl pl-64 font-bold">Photography</h1>
            </div>
            <p className="pl-5">Some of my best photography over the course of 2 years.</p>
        </>
    )
}
export default Photography;
